function validate([root]) {
  if (!Array.isArray(root) || root.length === 0) return 'The tree needs at least one node.';
  if (root.length > 16383) return 'The tree has at most 2^14 nodes.';
  // A perfect tree in level order has 2^k - 1 values and no gaps.
  if (((root.length + 1) & root.length) !== 0) return 'A perfect tree has 1, 3, 7, 15, ... nodes (2^k - 1).';
  if (root.some(v => v === null)) return 'A perfect tree has no missing nodes (no nulls).';
  if (root.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each node value is an integer from 0 to 10^5.';
  return null;
}

